exercises.solution:
.layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "head head"
    "side main"
    "foot foot";
  gap: 14px;
}

.head { grid-area: head; }
.side { grid-area: side; }
.main { grid-area: main; }
.foot { grid-area: foot; }
